from AlgorithmImports import *

class IndependentSmaAndRsiStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = [
            self.AddEquity("SPY", Resolution.Daily).Symbol,
            self.AddEquity("AAPL", Resolution.Daily).Symbol,
            self.AddEquity("IBM", Resolution.Daily).Symbol,
            self.AddEquity("BAC", Resolution.Daily).Symbol,
            self.AddEquity("AIG", Resolution.Daily).Symbol
        ]

        self.spy = self.Symbol("SPY")
        self.aapl = self.Symbol("AAPL")

        self.closes = {symbol: [] for symbol in self.symbols}
        self.aapl_red_streak = 0

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data):
        # Continuously update market-state data for every ticker that has a bar.
        for symbol in self.symbols:
            if not data.Bars.ContainsKey(symbol):
                continue

            close = data.Bars[symbol].Close
            history = self.closes[symbol]

            if symbol == self.aapl and len(history) > 0:
                if close < history[-1]:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            history.append(close)
            if len(history) > 101:
                history.pop(0)

        # Skip all rule evaluation when any subscribed ticker is missing today.
        if any(not data.Bars.ContainsKey(symbol) for symbol in self.symbols):
            return

        spy_closes = self.closes[self.spy]
        aapl_closes = self.closes[self.aapl]

        # Need 101 closes for yesterday's fully formed 100-day SMA and
        # today's fully formed 100-day SMA.
        spy_sma_ready = len(spy_closes) >= 101

        # Wilder RSI(14) requires 15 closes to be fully formed.
        aapl_rsi_ready = len(aapl_closes) >= 15

        # Sells are evaluated before buys.
        if self.strategy_a_shares > 0 and spy_sma_ready:
            yesterday_sma = sum(spy_closes[-101:-1]) / 100.0
            today_sma = sum(spy_closes[-100:]) / 100.0

            if spy_closes[-2] >= yesterday_sma and spy_closes[-1] < today_sma:
                self.MarketOrder(self.spy, -self.strategy_a_shares)
                self.strategy_a_shares = 0

        if self.strategy_b_shares > 0 and aapl_rsi_ready:
            rsi = self._WilderRsi(aapl_closes[-15:], 14)

            if rsi > 60:
                self.MarketOrder(self.aapl, -self.strategy_b_shares)
                self.strategy_b_shares = 0

        if self.strategy_a_shares == 0 and spy_sma_ready:
            yesterday_sma = sum(spy_closes[-101:-1]) / 100.0
            today_sma = sum(spy_closes[-100:]) / 100.0

            if spy_closes[-2] <= yesterday_sma and spy_closes[-1] > today_sma:
                target_value = self.Portfolio.TotalPortfolioValue * 0.40
                quantity = int(target_value / spy_closes[-1])

                if quantity > 0:
                    self.MarketOrder(self.spy, quantity)
                    self.strategy_a_shares = quantity

        if self.strategy_b_shares == 0 and len(aapl_closes) >= 2:
            if self.aapl_red_streak >= 1 and self.Portfolio.Cash >= 20000:
                quantity = int(20000 / aapl_closes[-1])

                if quantity > 0:
                    self.MarketOrder(self.aapl, quantity)
                    self.strategy_b_shares = quantity

    def _WilderRsi(self, closes, period):
        gains = []
        losses = []

        for i in range(1, len(closes)):
            change = closes[i] - closes[i - 1]
            gains.append(max(change, 0))
            losses.append(max(-change, 0))

        average_gain = sum(gains[:period]) / period
        average_loss = sum(losses[:period]) / period

        if average_loss == 0:
            return 100.0

        rs = average_gain / average_loss
        return 100.0 - (100.0 / (1.0 + rs))
