from AlgorithmImports import *
import math


class PrivateLotStrategySystem(QCAlgorithm):

    RED_CONSECUTIVE_DAYS = 3

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)
        self.SetWarmUp(101, Resolution.Daily)

        self.symbols = {
            ticker: self.AddEquity(ticker, Resolution.Daily).Symbol
            for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        }

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(14)

        self.previous_closes = {}
        self.aapl_red_streak = 0
        self.previous_spy_sma = None

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data):
        # Market-state quantities update continuously whenever a ticker bar exists.
        for symbol in self.symbols.values():
            if symbol not in data.Bars:
                continue

            bar = data.Bars[symbol]
            close = bar.Close

            if symbol == self.spy:
                self.spy_sma.Update(bar.EndTime, close)

            if symbol == self.aapl:
                self.aapl_rsi.Update(bar.EndTime, close)

                if symbol in self.previous_closes and close < self.previous_closes[symbol]:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.previous_closes[symbol] = close

        all_bars_present = all(symbol in data.Bars for symbol in self.symbols.values())

        if self.IsWarmingUp:
            if self.spy_sma.IsReady:
                self.previous_spy_sma = self.spy_sma.Current.Value
            return

        if not all_bars_present:
            if self.spy_sma.IsReady:
                self.previous_spy_sma = self.spy_sma.Current.Value
            return

        spy_close = data.Bars[self.spy].Close
        aapl_close = data.Bars[self.aapl].Close

        # Sells are evaluated before buys.
        if self.strategy_a_shares > 0:
            crosses_below = (
                self.previous_spy_sma is not None
                and self.previous_closes.get(self.spy) is not None
                and self.previous_closes[self.spy] < self.previous_spy_sma
                and spy_close < self.spy_sma.Current.Value
            )
            if crosses_below:
                self.MarketOrder(self.spy, -self.strategy_a_shares)
                self.strategy_a_shares = 0

        if self.strategy_b_shares > 0 and self.aapl_rsi.IsReady:
            if self.aapl_rsi.Current.Value > 60:
                self.MarketOrder(self.aapl, -self.strategy_b_shares)
                self.strategy_b_shares = 0

        if (
            self.strategy_a_shares == 0
            and self.spy_sma.IsReady
            and self.previous_spy_sma is not None
        ):
            previous_spy_close = self.previous_closes.get(self.spy)
            crosses_above = (
                previous_spy_close is not None
                and previous_spy_close <= self.previous_spy_sma
                and spy_close > self.spy_sma.Current.Value
            )

            if crosses_above:
                shares = int(math.floor(
                    0.40 * float(self.Portfolio.TotalPortfolioValue) / float(spy_close)
                ))
                if shares > 0:
                    self.MarketOrder(self.spy, shares)
                    self.strategy_a_shares = shares

        if (
            self.strategy_b_shares == 0
            and self.aapl_rsi.IsReady
            and self.aapl_red_streak >= self.RED_CONSECUTIVE_DAYS
            and self.Portfolio.Cash >= 20_000
        ):
            shares = int(math.floor(20_000 / float(aapl_close)))
            if shares > 0:
                self.MarketOrder(self.aapl, shares)
                self.strategy_b_shares = shares

        if self.spy_sma.IsReady:
            self.previous_spy_sma = self.spy_sma.Current.Value
